{"function":"async () => {
const out = {};
const props = ['outline-style','outline-width','outline-color','box-shadow','border-color','border-width','background-color'];
for (const id of ['nome','servico','unidade','cpf','descricao']) {
  const el = document.getElementById(id);
  el.blur();
  const before = Object.fromEntries(props.map(p=>[p,getComputedStyle(el).getPropertyValue(p)]));
  el.focus();
  await new Promise(r=>setTimeout(r,50));
  const after = Object.fromEntries(props.map(p=>[p,getComputedStyle(el).getPropertyValue(p)]));
  out[id] = {before, after, fv: el.matches(':focus-visible')};
  el.blur();
}
// h1 font
const h1 = document.querySelector('h1');
out.h1 = getComputedStyle(h1).fontSize;
// presencial label geometry
const lab = document.querySelector('#forma-presencial + label');
out.presencialLabel = lab.getBoundingClientRect().toJSON();
out.upload = [...document.querySelectorAll('.br-upload *')].map(e=>({tag:e.tagName,cls:e.className, r:e.getBoundingClientRect().toJSON(), disp:getComputedStyle(e).display, op:getComputedStyle(e).opacity}));
out.breadcrumb = document.querySelector('.br-breadcrumb').getBoundingClientRect().toJSON();
out.header = document.querySelector('header').getBoundingClientRect().toJSON();
return out;
}"}

